import json
import csv
import sys

def flatten_json(y, prefix=''):
    out = {}
    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], f'{name}{a}.')
        elif isinstance(x, list):
            i = 0
            for a in x:
                flatten(a, f'{name}{i}.')
                i += 1
        else:
            out[name[:-1]] = x
    flatten(y, prefix)
    return out

def main(input_file, output_file):
    with open(input_file, 'r') as f:
        data = json.load(f)

    flat_data = []
    if isinstance(data, list):
        for entry in data:
            flat_data.append(flatten_json(entry))
    else:
        flat_data.append(flatten_json(data))

    all_keys = sorted(set(k for d in flat_data for k in d.keys()))

    with open(output_file, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=all_keys)
        writer.writeheader()
        for row in flat_data:
            writer.writerow(row)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print(f'Usage: {sys.argv[0]} input.json output.csv')
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])
